    if n < 65:
        return {"target": pos, "stop": None, "take": None}

    # Current bar is not tradable until next open, so use completed bars up to current close.
    close = float(c[-1])

    # 64-bar box from the prior 64 bars, excluding current bar
    box_high = float(ind.highest(h[:-1], 64)[-1])
    box_low = float(ind.lowest(l[:-1], 64)[-1])
    box_height = box_high - box_low

    atr14 = ind.atr(hist, 14)
    cur_atr = float(atr14[-1])
    if not math.isfinite(cur_atr) or cur_atr <= 0:
        return {"target": pos, "stop": None, "take": None}

    # Ignore boxes wider than 6 ATR
    if box_height > 6.0 * cur_atr:
        signal = 0
    else:
        signal = 0
        if close > box_high:
            signal = 1
        elif close < box_low:
            signal = -1

    # 1h filter: last completed 1h candle on the right side of its 50 EMA
    h1 = hist.htf(60)
    if len(h1.close) < 50:
        htf_ok_long = False
        htf_ok_short = False
    else:
        h1_close = h1.close
        h1_ema50 = ind.ema(h1_close, 50)
        last_close = float(h1_close[-1])
        last_ema = float(h1_ema50[-1])
        htf_ok_long = last_close > last_ema
        htf_ok_short = last_close < last_ema

    desired = pos
    if pos == 0.0:
        if signal == 1 and htf_ok_long:
            desired = 0.25
        elif signal == -1 and htf_ok_short:
            desired = -0.25
    else:
        # Opposite signal closes the trade; do not reverse.
        if pos > 0 and signal == -1:
            desired = 0.0
        elif pos < 0 and signal == 1:
            desired = 0.0
        else:
            # Time stop after 32 bars in trade
            entry_bar = state.get("entry_bar", -1)
            if entry_bar >= 0 and (n - 1 - entry_bar) >= 32:
                desired = 0.0

    # Update trade state
    if pos == 0.0 and desired != 0.0:
        state["entry_bar"] = n - 1
        state["entry_dir"] = 1 if desired > 0 else -1
    elif desired == 0.0:
        if pos != 0.0:
            state["entry_bar"] = -1
            state["entry_dir"] = 0

    return {"target": desired, "stop": None, "take": None}

