    def get_int(key, default=0):
        v = state.get(key, default)
        return int(v) if isinstance(v, (int, np.integer, bool)) else int(default)

    def get_float(key, default=0.0):
        v = state.get(key, default)
        return float(v) if isinstance(v, (int, float, np.integer, np.floating, bool)) else float(default)

    def set_int(key, value):
        state[key] = int(value)

    def set_float(key, value):
        state[key] = float(value)

    in_pos = pos > 0.0

    if not in_pos:
        if "entry_bar" in state:
            del state["entry_bar"]
        if "entry_price" in state:
            del state["entry_price"]
        if "entry_atr" in state:
            del state["entry_atr"]
        if "adds" in state:
            del state["adds"]
        if "last_add_price" in state:
            del state["last_add_price"]
        if "breakeven" in state:
            del state["breakeven"]

    # Signals
    bull_cross = False
    bear_cross = False
    if i >= 1 and not (math.isnan(macd_line[i]) or math.isnan(signal_line[i]) or math.isnan(macd_line[i - 1]) or math.isnan(signal_line[i - 1])):
        bull_cross = macd_line[i - 1] <= signal_line[i - 1] and macd_line[i] > signal_line[i]
        bear_cross = macd_line[i - 1] >= signal_line[i - 1] and macd_line[i] < signal_line[i]

    # Time exit after 256 bars since signal
    if in_pos and "entry_bar" in state:
        if i - int(state["entry_bar"]) >= 256:
            return {"target": 0.0, "stop": None, "take": None}

    # Opposite signal just exits flat
    if in_pos and bear_cross:
        return {"target": 0.0, "stop": None, "take": None}

    # Entry
    if not in_pos:
        if bull_cross and not math.isnan(atr[i]) and atr[i] > 0:
            state["entry_bar"] = i
            state["entry_price"] = float(cur_close)
            state["entry_atr"] = float(atr[i])
            state["adds"] = 0
            state["last_add_price"] = float(cur_close)
            state["breakeven"] = False
            return {"target": 0.25, "stop": None, "take": None}
        return {"target": float(pos), "stop": None, "take": None}

    # Manage existing long
    entry_price = get_float("entry_price", cur_close)
    entry_atr = get_float("entry_atr", atr[i] if not math.isnan(atr[i]) else 0.0)
    adds = get_int("adds", 0)
    last_add_price = get_float("last_add_price", entry_price)
    breakeven = bool(state.get("breakeven", False))

    target = float(pos)

    # Pyramid with at most 1 add, each add by quarter size, capped at full size
    if adds < 1 and not math.isnan(atr[i]) and atr[i] > 0:
        if cur_close >= last_add_price + 2.0 * entry_atr:
