                state["adds"] = adds + 1
                state["last_add_price"] = float(cur_close)

    # Move stop to breakeven once candle closes in green by at least 1.5 ATR
    if not breakeven and not math.isnan(atr[i]) and atr[i] > 0:
        if cur_close >= entry_price + 1.5 * entry_atr:
            state["breakeven"] = True
            breakeven = True

    stop = entry_price if breakeven else None

    return {"target": target, "stop": stop, "take": None}

