    entry_price = float(state.get("entry_price", 0.0))
    entry_atr = float(state.get("entry_atr", 0.0))
    peak_close = float(state.get("peak_close", 0.0))

    flat = abs(pos) < 1e-12
    long_pos = pos > 0.0

    if flat:
        if n > 96 and math.isfinite(prior96_high) and c > prior96_high and atr_ok:
            raw = 0.0025 * c / (2.0 * atr)
            raw = max(0.05, min(1.0, raw))
            target = float(np.round(raw / 0.05) * 0.05)
            if target < 0.05:
                target = 0.05
            state["entry_bar"] = n - 1
            state["entry_price"] = c
            state["entry_atr"] = atr
            state["peak_close"] = c
            state["entry_signal"] = 1
        else:
            if "entry_bar" in state:
                del state["entry_bar"]
            if "entry_price" in state:
                del state["entry_price"]
            if "entry_atr" in state:
                del state["entry_atr"]
            if "peak_close" in state:
                del state["peak_close"]
            if "entry_signal" in state:
                del state["entry_signal"]
        return {"target": target, "stop": None, "take": None}

    if n > 96 and math.isfinite(prior96_low) and c < prior96_low:
        target = 0.0
        return {"target": target, "stop": None, "take": None}

    if entry_bar >= 0 and (n - 1) - entry_bar >= 64:
        target = 0.0
        return {"target": target, "stop": None, "take": None}

    if not (math.isfinite(entry_atr) and entry_atr > 0.0):
        entry_atr = atr if atr_ok else 0.0

    if long_pos:
        if c > peak_close:
            peak_close = c

        profit = c - entry_price
        if profit >= 1.5 * entry_atr:
            stop = entry_price

        box_steps = 0
        if entry_atr > 0.0:
            box_steps = int(math.floor((peak_close - entry_price) / entry_atr))
