                box_steps = 0

        stop_level = entry_price - 2.0 * entry_atr + box_steps * entry_atr
        take_level = entry_price + 3.0 * entry_atr + box_steps * entry_atr

        if stop is None or stop_level > stop:
            stop = stop_level
        take = take_level

        state["entry_bar"] = entry_bar
        state["entry_price"] = entry_price
        state["entry_atr"] = entry_atr
        state["peak_close"] = peak_close

    return {"target": target, "stop": stop, "take": take}

