    box_hi = ind.highest(high[-(box_len + 1):-1], box_len)[-1] if len(hist) >= box_len + 1 else np.nan
    box_lo = ind.lowest(low[-(box_len + 1):-1], box_len)[-1] if len(hist) >= box_len + 1 else np.nan
    if not np.isfinite(box_hi) or not np.isfinite(box_lo):
        return {"target": pos, "stop": None, "take": None}

