    l48 = float(ind.lowest(low[:-1], 48)[-1]) if len(low) > 1 else float("nan")

    target = pos
    stop = None
    take = None

    if pos == 0.0:
        long_signal = math.isfinite(h48) and c > h48
        short_signal = math.isfinite(l48) and c < l48
        if long_signal and not short_signal:
            risk = 0.01
            frac = risk * c / (3.0 * a)
            if frac > 1.0:
                frac = 1.0
            if frac < 0.05:
                frac = 0.05
            target = frac
            state["entry_dir"] = 1
            state["entry_atr"] = a
            state["entry_px"] = c
            state["best_px"] = c
            state["trail_on"] = 0
            state["be_on"] = 0
        elif short_signal and not long_signal:
            risk = 0.01
            frac = risk * c / (3.0 * a)
            if frac > 1.0:
                frac = 1.0
            if frac < 0.05:
