    if direction > 0:
        if c > best_px:
            best_px = c
        if (not be_on) and c >= entry_px + entry_atr:
            be_on = True
            trail_on = True
        stop_level = entry_px - 1.5 * entry_atr
        if be_on:
            stop_level = max(stop_level, entry_px)
        if trail_on:
            stop_level = max(stop_level, best_px - 3.0 * entry_atr)
        stop = stop_level
        target = pos
        if c < l48:
            target = 0.0
            stop = None
            take = None
            for k in ("entry_dir", "entry_atr", "entry_px", "best_px", "trail_on", "be_on"):
                if k in state:
                    del state[k]
            return {"target": target, "stop": stop, "take": take}
