def strategy(hist, state, pos, ind) -> dict:
    n = len(hist)
    target = float(pos)
    stop = None
    take = None

    if n < 51:
        return {"target": target, "stop": stop, "take": take}

    close = hist.close
    sma5 = ind.sma(close, 5)
    sma50 = ind.sma(close, 50)
    atr14 = ind.atr(hist, 14)

    i = n - 1
    prev = i - 1

    if np.isnan(sma5[prev]) or np.isnan(sma50[prev]) or np.isnan(sma5[i]) or np.isnan(sma50[i]) or np.isnan(atr14[i]):
        return {"target": target, "stop": stop, "take": take}

    prev_diff = sma5[prev] - sma50[prev]
    curr_diff = sma5[i] - sma50[i]

    bull_cross = prev_diff <= 0.0 and curr_diff > 0.0
    bear_cross = prev_diff >= 0.0 and curr_diff < 0.0

    cooldown_until = int(state.get("cooldown_until", -1))
    entry_bar = int(state.get("entry_bar", -1))
    entry_dir = int(state.get("entry_dir", 0))

    in_trade = pos != 0.0

    if in_trade:
        if entry_bar >= 0 and i >= entry_bar + 16:
            target = 0.0
            state["cooldown_until"] = i + 4
            state["entry_bar"] = -1
            state["entry_dir"] = 0
            return {"target": target, "stop": stop, "take": take}

        if pos > 0.0 and bear_cross:
            target = 0.0
            state["cooldown_until"] = i + 4
            state["entry_bar"] = -1
            state["entry_dir"] = 0
            return {"target": target, "stop": stop, "take": take}

        if pos < 0.0 and bull_cross:
            target = 0.0
            state["cooldown_until"] = i + 4
            state["entry_bar"] = -1
            state["entry_dir"] = 0
            return {"target": target, "stop": stop, "take": take}

        target = pos
        return {"target": target, "stop": stop, "take": take}

    if cooldown_until >= 0 and i < cooldown_until:
        return {"target": target, "stop": stop, "take": take}

    if bull_cross or bear_cross:
        atr = float(atr14[i])
        if not np.isnan(atr) and atr > 0.0:
            size = 0.0025 * float(close[i]) / atr
            if size < 0.05:
                size = 0.05
            if size > 1.0:
                size = 1.0
            size = round(size / 0.05) * 0.05
            if size < 0.05:
                size = 0.05
            if bull_cross:
                target = size
                state["entry_bar"] = i
                state["entry_dir"] = 1
                state["cooldown_until"] = -1
            elif bear_cross:
                target = -size
                state["entry_bar"] = i
                state["entry_dir"] = -1
                state["cooldown_until"] = -1

    return {"target": target, "stop": stop, "take": take}

