    h4 = hist.htf(240)
    h4_close = h4.close
    h4_ema20 = ind.ema(h4_close, 20)
    h4_ok_long = False
    h4_ok_short = False
    if len(h4_close) > 0:
        h4_ok_long = h4_close[-1] > h4_ema20[-1] if not np.isnan(h4_ema20[-1]) else False
        h4_ok_short = h4_close[-1] < h4_ema20[-1] if not np.isnan(h4_ema20[-1]) else False

    # 4-hour box = prior 4 hours = prior 16 bars, excluding current bar
    box_n = 16
    if n < box_n + 1:
        return {"target": float(pos), "stop": None, "take": None}

    box_high = float(np.max(high[-box_n-1:-1]))
    box_low = float(np.min(low[-box_n-1:-1]))

    atr14 = ind.atr(hist, 14)
    atr = float(atr14[-1])
    if not np.isfinite(atr) or atr <= 0:
        return {"target": float(pos), "stop": None, "take": None}

    box_height = box_high - box_low
    if not np.isfinite(box_height) or box_height > 6.0 * atr:
        box_ok = False
    else:
        box_ok = True

    target = float(pos)
    stop = None
    take = None

    entry_price = float(cur)
    entry_atr = atr

    # Manage live position: BE stop once 2 ATR in profit on a close
    if pos > 0:
        if cur >= entry_price + 2.0 * entry_atr:
            stop = max(stop if stop is not None else -1e100, entry_price)
    elif pos < 0:
        if cur <= entry_price - 2.0 * entry_atr:
            stop = min(stop if stop is not None else 1e100, entry_price)

    # Signals only when flat; opposite signal closes existing position next open
    long_sig = box_ok and h4_ok_long and cur > box_high
    short_sig = box_ok and h4_ok_short and cur < box_low

    if pos == 0.0:
        if state.get("entries", 0) < 2:
            if long_sig and not short_sig:
                size = 0.005 * entry_price / entry_atr
                size = max(0.05, min(1.0, size))
                target = round(size / 0.05) * 0.05
                if target > 1.0:
                    target = 1.0
                if target < 0.05:
                    target = 0.05
                state["entries"] = int(state.get("entries", 0)) + 1
            elif short_sig and not long_sig:
                size = 0.005 * entry_price / entry_atr
                size = max(0.05, min(1.0, size))
                target = -round(size / 0.05) * 0.05
                if target < -1.0:
                    target = -1.0
                if target > -0.05:
                    target = -0.05
                state["entries"] = int(state.get("entries", 0)) + 1
    else:
        if pos > 0 and short_sig:
            target = 0.0
        elif pos < 0 and long_sig:
            target = 0.0

    return {"target": float(target), "stop": None if stop is None else float(stop), "take": None}

