    # Need enough history for breakout and ATR
    if t < 48 or not np.isfinite(atr) or atr <= 0:
        return {"target": float(pos), "stop": None, "take": None}

    prior_high = float(np.max(high[-49:-1]))
    prior_low = float(np.min(low[-49:-1]))
    c = float(close[-1])

    long_signal = c > prior_high
    short_signal = c < prior_low

    # Position sizing: risk 0.25% of equity per 3 ATR, capped at 1.0, floored at 0.05.
    risk = 0.0025
    k = 3.0
    target_size = risk * c / (k * atr)
    if target_size > 1.0:
        target_size = 1.0
    if target_size < 0.05:
        target_size = 0.05

    # Persistent trade state
    direction = int(state.get("direction", 0))   # 1 long, -1 short, 0 flat
    extreme = float(state.get("extreme", c))     # highest high for long, lowest low for short

    # If flat, react to breakouts.
    if pos == 0.0 or direction == 0:
        state["direction"] = 0
        state["extreme"] = c
        if long_signal and not short_signal:
            state["direction"] = 1
            state["extreme"] = float(high[-1])
            stop = state["extreme"] - 2.0 * atr
            return {"target": float(target_size), "stop": float(stop), "take": None}
        if short_signal and not long_signal:
            state["direction"] = -1
            state["extreme"] = float(low[-1])
            stop = state["extreme"] + 2.0 * atr
            return {"target": float(-target_size), "stop": float(stop), "take": None}
        return {"target": float(pos), "stop": None, "take": None}

    # If in a position, update trailing extreme.
    if pos > 0:
        direction = 1
        if "extreme" not in state or not np.isfinite(extreme):
            extreme = float(high[-1])
        extreme = max(extreme, float(high[-1]))
        state["direction"] = 1
        state["extreme"] = extreme

        # Opposing breakout while long -> exit flat next open.
        if short_signal:
            return {"target": 0.0, "stop": None, "take": None}

        stop = extreme - 2.0 * atr
        return {"target": float(pos), "stop": float(stop), "take": None}

    if pos < 0:
        direction = -1
        if "extreme" not in state or not np.isfinite(extreme):
            extreme = float(low[-1])
        extreme = min(extreme, float(low[-1]))
        state["direction"] = -1
        state["extreme"] = extreme

        # Opposing breakout while short -> exit flat next open.
        if long_signal:
            return {"target": 0.0, "stop": None, "take": None}

        stop = extreme + 2.0 * atr
        return {"target": float(pos), "stop": float(stop), "take": None}

    return {"target": float(pos), "stop": None, "take": None}

