def strategy(hist, state, pos, ind) -> dict:
    i = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    # Warmup / safety
    if i < 1000:
        return {"target": pos, "stop": None, "take": None}

    # Persistent state defaults
    if "last_flat_i" not in state:
        state["last_flat_i"] = -10**9
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "anchor" not in state:
        state["anchor"] = 0.0
    if "dir" not in state:
        state["dir"] = 0

    # Detect exits to start cooldown.
    # We infer "just exited" when currently flat and we had a remembered trade.
    if pos == 0.0 and state["dir"] != 0:
        state["last_flat_i"] = i
        state["dir"] = 0
        state["entry_price"] = 0.0
        state["entry_atr"] = 0.0
        state["anchor"] = 0.0

    # Cooldown after any exit: 96 bars
    if pos == 0.0 and (i - state["last_flat_i"] < 96):
        return {"target": 0.0, "stop": None, "take": None}

    # Indicators
    atr14 = ind.atr(hist, 14)[-1]
    ema4h50 = ind.ema(hist.htf(240).close, 50)[-1]

    # Donchian channel on 96 prior 15m bars, excluding current bar
    prior_high_96 = ind.highest(hist.high[:-1], 96)[-1] if len(hist) >= 97 else np.nan
    prior_low_96 = ind.lowest(hist.low[:-1], 96)[-1] if len(hist) >= 97 else np.nan

    if np.isnan(atr14) or atr14 <= 0 or np.isnan(ema4h50) or np.isnan(prior_high_96) or np.isnan(prior_low_96):
        return {"target": pos, "stop": None, "take": None}

    # Signal conditions
    long_sig = close > prior_high_96 and close > ema4h50
    short_sig = close < prior_low_96 and close < ema4h50

    # Position sizing: risk 0.5% per 3 ATR, capped at 1.0 and floored at 0.05
    raw_size = 0.005 * close / (3.0 * atr14)
    target_size = min(1.0, max(0.05, raw_size))

    # Entry / flip logic
    if pos == 0.0:
        if long_sig:
            state["dir"] = 1
            state["entry_price"] = close
            state["entry_atr"] = atr14
            state["anchor"] = close
            return {"target": target_size, "stop": close - atr14, "take": close + 2.0 * atr14}
        if short_sig:
            state["dir"] = -1
            state["entry_price"] = close
            state["entry_atr"] = atr14
            state["anchor"] = close
            return {"target": -target_size, "stop": close + atr14, "take": close - 2.0 * atr14}
        return {"target": 0.0, "stop": None, "take": None}

    # Active trade management
    d = 1 if pos > 0 else -1
    ep = state["entry_price"]
    ea = state["entry_atr"]
    anchor = state["anchor"] if state["anchor"] != 0.0 else ep

    # Opposite signal exits next open, no reversal
    if d == 1 and short_sig:
        return {"target": 0.0, "stop": None, "take": None}
    if d == -1 and long_sig:
        return {"target": 0.0, "stop": None, "take": None}

    # Ratchet logic: initial anchor is entry; every +2 ATR in profit past anchor, move anchor by 2 ATR.
    if d == 1:
        while close >= anchor + 2.0 * ea:
            anchor += 2.0 * ea
    else:
        while close <= anchor - 2.0 * ea:
            anchor -= 2.0 * ea
    state["anchor"] = anchor

    # Stop/take relative to anchor
    if d == 1:
        stop = anchor - ea
        take = anchor + 2.0 * ea
        if close >= ep + 0.5 * ea:
            stop = max(stop, ep)
    else:
        stop = anchor + ea
        take = anchor - 2.0 * ea
        if close <= ep - 0.5 * ea:
            stop = min(stop, ep)

    return {"target": pos, "stop": stop, "take": take}

