    n = len(hist)
    if n < 50:
        return {"target": pos, "stop": None, "take": None}

    don_len = 48
    cooldown_bars = 48
    max_age = 256
    add_step_atr = 2.0

    # Indicators
    atr14 = ind.atr(hist, 14)
    atr = float(atr14[-1])

    # Donchian levels based on prior 48 bars (exclude current bar)
    if n <= don_len:
        return {"target": pos, "stop": None, "take": None}
    prior_high = float(np.max(high[-don_len-1:-1]))
    prior_low = float(np.min(low[-don_len-1:-1]))

    c = float(close[-1])
    p = float(close[-2])

    # Persistent state
    st_dir = int(state.get("dir", 0))          # 1 long, -1 short, 0 flat
    st_entry = float(state.get("entry", 0.0))  # signal bar index
    st_adds = int(state.get("adds", 0))
    st_last_add = float(state.get("last_add", 0.0))
    st_cd = int(state.get("cooldown_until", -1))

    cur_index = n - 1

    # Detect fresh flat/open state from position
    if pos == 0.0 and st_dir != 0:
        st_dir = 0
        st_entry = 0.0
        st_adds = 0
        st_last_add = 0.0

    # Exit logic while in position
    if pos > 0:
        # Opposite Donchian signal or max age => exit at next open
        if c < prior_low or (st_entry > 0 and (cur_index - int(st_entry)) >= max_age):
            state["dir"] = 0
            state["entry"] = 0.0
            state["adds"] = 0
            state["last_add"] = 0.0
            state["cooldown_until"] = cur_index + cooldown_bars if pos == 0 else st_cd
            return {"target": 0.0, "stop": None, "take": None}

        # Pyramiding: one add per trade, another quarter size, up to full port
        target = pos
        if st_adds < 1 and atr > 0.0:
            if c >= st_last_add + add_step_atr * atr and pos < 1.0:
                target = min(1.0, round((pos + 0.25) / 0.05) * 0.05)
                if target > pos:
                    state["adds"] = 1
                    state["last_add"] = c
                    return {"target": target, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    if pos < 0:
        if c > prior_high or (st_entry > 0 and (cur_index - int(st_entry)) >= max_age):
            state["dir"] = 0
            state["entry"] = 0.0
            state["adds"] = 0
            state["last_add"] = 0.0
            state["cooldown_until"] = cur_index + cooldown_bars if pos == 0 else st_cd
            return {"target": 0.0, "stop": None, "take": None}

        target = pos
        if st_adds < 1 and atr > 0.0:
            if c <= st_last_add - add_step_atr * atr and pos > -1.0:
                target = max(-1.0, round((pos - 0.25) / 0.05) * 0.05)
                if target < pos:
                    state["adds"] = 1
                    state["last_add"] = c
                    return {"target": target, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    # Flat: enforce cooldown
    if cur_index < st_cd:
        return {"target": 0.0, "stop": None, "take": None}

    # Entry signals only while flat
    if c > prior_high:
        state["dir"] = 1
        state["entry"] = cur_index
        state["adds"] = 0
        state["last_add"] = c
        return {"target": 0.25, "stop": None, "take": None}

    if c < prior_low:
        state["dir"] = -1
        state["entry"] = cur_index
        state["adds"] = 0
        state["last_add"] = c
        return {"target": -0.25, "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

