        len(hist) > 1
        and not np.isnan(p5) and not np.isnan(p100) and not np.isnan(e5) and not np.isnan(e100)
        and p5 <= p100 and e5 > e100
    )
    bear_cross = (
        len(hist) > 1
        and not np.isnan(p5) and not np.isnan(p100) and not np.isnan(e5) and not np.isnan(e100)
        and p5 >= p100 and e5 < e100
    )

