    day = int(hist.time[-1] // 86400000)
    if state.get("day", -1) != day:
        state["day"] = day
        state["day_trades"] = 0
        state["had_trade"] = 0

    # Completed 1h candle trend filter
    h1 = hist.htf(60)
    if len(h1) < 51:
        return {"target": target, "stop": stop, "take": take}

    ema50_1h = ind.ema(h1.close, 50)
    trend_long = h1.close[-1] > ema50_1h[-1]
    trend_short = h1.close[-1] < ema50_1h[-1]

    # 15m breakout box over prior 32 bars
    if n < 33:
        return {"target": target, "stop": stop, "take": take}

    box_high = float(np.max(hist.high[-33:-1]))
    box_low = float(np.min(hist.low[-33:-1]))
    box_height = box_high - box_low

    atr14 = ind.atr(hist, 14)
    cur_atr = float(atr14[-1])
    if not np.isfinite(cur_atr) or cur_atr <= 0:
        return {"target": target, "stop": stop, "take": take}

    long_break = hist.close[-1] > box_high
    short_break = hist.close[-1] < box_low
    box_ok = box_height <= 6.0 * cur_atr

    # Volatility-scaled size: 1% of equity per 2 ATR => 0.01 * close / (2 * ATR)
    size = 0.01 * float(hist.close[-1]) / (2.0 * cur_atr)
    size = max(0.05, min(1.0, size))
    size = round(size / 0.05) * 0.05
    size = max(0.05, min(1.0, size))

    # Limit entries to max 3 per UTC calendar day
    entries_today = int(state.get("entries_today", 0))

    # Existing position management: opposite signal closes out, no reversal
    if pos > 0:
        if short_break:
            target = 0.0
        return {"target": target, "stop": stop, "take": take}

    if pos < 0:
        if long_break:
            target = 0.0
        return {"target": target, "stop": stop, "take": take}

    # Flat: consider fresh entries
    if entries_today >= 3 or not box_ok:
        return {"target": target, "stop": stop, "take": take}

    if long_break and trend_long:
        target = size
        state["entries_today"] = entries_today + 1
    elif short_break and trend_short:
        target = -size
        state["entries_today"] = entries_today + 1

    return {"target": target, "stop": stop, "take": take}

