    if not math.isfinite(atr) or atr <= 0.0:
        return {"target": pos, "stop": None, "take": None}

    n = len(hist)
    breakout_len = 96
    arm_bars = 16

    # Persisted state
    mode = int(state.get("mode", 0))  # 0 idle, 1 long armed, -1 short armed, 2 long live, -2 short live
    arm_expiry = int(state.get("arm_expiry", -1))
    breakout_level = float(state.get("breakout_level", float("nan")))
    entry_atr = float(state.get("entry_atr", float("nan")))
    entry_price = float(state.get("entry_price", float("nan")))
    scale_done = bool(state.get("scale_done", False))
    base_target = float(state.get("base_target", 0.0))

    # 96-bar Donchian levels using prior bars only
    if n >= breakout_len + 1:
        prior_high = float(np.max(hist.high[-(breakout_len + 1):-1]))
        prior_low = float(np.min(hist.low[-(breakout_len + 1):-1]))
    else:
        prior_high = float("nan")
        prior_low = float("nan")

    target = pos
    stop = None
    take = None

    # Live trade management
    if mode == 2 and pos > 0:
        if math.isfinite(entry_atr):
            stop = entry_price - 2.0 * entry_atr
            take = entry_price + 4.0 * entry_atr
        else:
            stop = None
            take = None

        if math.isfinite(entry_atr) and not scale_done:
            if c >= entry_price + 3.0 * entry_atr:
                half = round((base_target / 2.0) / 0.05) * 0.05
                if half < 0.0:
                    half = 0.0
                target = half
                state["scale_done"] = True
                scale_done = True
            else:
                target = pos

    elif mode == -2 and pos < 0:
        if math.isfinite(entry_atr):
            stop = entry_price + 2.0 * entry_atr
            take = entry_price - 4.0 * entry_atr
        else:
            stop = None
            take = None

        if math.isfinite(entry_atr) and not scale_done:
            if c <= entry_price - 3.0 * entry_atr:
                half = round((base_target / 2.0) / 0.05) * 0.05
                if half > 0.0:
                    half = -half
                target = half
                state["scale_done"] = True
                scale_done = True
            else:
                target = pos

    # Signal generation only when flat
    if pos == 0.0:
        # If an armed setup exists, wait for retest within the arm window
        if mode == 1 and n <= arm_expiry:
            if math.isfinite(breakout_level) and l <= breakout_level:
                raw = 0.0025 * c / atr
                raw = min(1.0, max(0.05, raw))
                target = round(raw / 0.05) * 0.05
                state["mode"] = 2
                state["entry_atr"] = atr
                state["entry_price"] = c
                state["scale_done"] = False
                state["base_target"] = target
            elif n > arm_expiry:
                state["mode"] = 0

        elif mode == -1 and n <= arm_expiry:
            if math.isfinite(breakout_level) and h >= breakout_level:
                raw = 0.0025 * c / atr
                raw = min(1.0, max(0.05, raw))
                target = -round(raw / 0.05) * 0.05
                state["mode"] = -2
                state["entry_atr"] = atr
                state["entry_price"] = c
                state["scale_done"] = False
                state["base_target"] = target
            elif n > arm_expiry:
                state["mode"] = 0

        # Fresh breakout arms the setup
        if mode == 0 and n >= breakout_len + 1:
            if c > prior_high:
                state["mode"] = 1
                state["breakout_level"] = prior_high
                state["arm_expiry"] = n + arm_bars - 1
            elif c < prior_low:
                state["mode"] = -1
                state["breakout_level"] = prior_low
                state["arm_expiry"] = n + arm_bars - 1

        # Opposite signal flips to flat: if armed opposite to any existing live position, flatten next open.
        if pos > 0 and mode == -2:
            target = 0.0
        elif pos < 0 and mode == 2:
            target = 0.0

    # Clean up stale armed setups
    if mode in (1, -1) and n > arm_expiry:
        state["mode"] = 0

    # Ensure live mode persists after entry
    if pos != 0.0:
        if state.get("mode", 0) == 0:
            state["mode"] = 2 if pos > 0 else -2

    return {"target": float(target), "stop": stop, "take": take}

