    n = len(hist)
    i = n - 1

    # State init / defaults
    if "flat_until" not in state:
        state["flat_until"] = 0
    if "base" not in state:
        state["base"] = 0.0
    if "last_add" not in state:
        state["last_add"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "entry_px" not in state:
        state["entry_px"] = 0.0

