    if pos == 0.0:
        state["base"] = 0.0
        state["last_add"] = 0.0
        state["entry_atr"] = 0.0
        state["entry_px"] = 0.0
    else:
        if state["base"] == 0.0:
            state["base"] = abs(pos)
            state["last_add"] = abs(pos)
            state["entry_atr"] = float(atr[i]) if not math.isnan(float(atr[i])) else 0.0
            state["entry_px"] = float(close[i])

    # Cooldown after trade ends
    if pos == 0.0 and state.get("prev_pos", 0.0) != 0.0:
        state["flat_until"] = i + 16

    state["prev_pos"] = pos

    # Need enough history for Donchian + HTF EMA
    if i < 96 or len(htf60) < 50 or math.isnan(float(ema50[-1])) or math.isnan(float(atr[i])):
        return {"target": pos, "stop": None, "take": None}

    # Donchian levels: prior 96 bars before current bar
    dc_high = float(ind.highest(hist.high[-97:-1], 96)[-1])
    dc_low = float(ind.lowest(hist.low[-97:-1], 96)[-1])

    ema_now = float(ema50[-1])
    c = float(close[i])
    a = float(atr[i])

    long_signal = c > dc_high and c > ema_now
    short_signal = c < dc_low and c < ema_now

    # If in position, manage exits / pyramids
    if pos != 0.0:
        side = 1.0 if pos > 0 else -1.0
        base = float(state.get("base", abs(pos)))
        entry_atr = float(state.get("entry_atr", a))
        last_add = float(state.get("last_add", abs(pos)))

        # Opposite signal flips flat only
        if (side > 0 and short_signal) or (side < 0 and long_signal):
            return {"target": 0.0, "stop": None, "take": None}

        # Hard stop / take profit using entry ATR
        stop = None
        take = None
        if side > 0:
            stop = float(state.get("entry_px", c) - 1.5 * entry_atr) if entry_atr > 0 else c - 1.5 * a
            take = float(state.get("entry_px", c) + 2.0 * entry_atr) if entry_atr > 0 else c + 2.0 * a
        else:
            stop = float(state.get("entry_px", c) + 1.5 * entry_atr) if entry_atr > 0 else c + 1.5 * a
            take = float(state.get("entry_px", c) - 2.0 * entry_atr) if entry_atr > 0 else c - 2.0 * a

        # Pyramid up to two more times, half-size each time, cap total size at full port
        target = pos
        if base > 0:
            max_pos = 1.0
            add_size = min(base, max_pos - abs(pos))
            if add_size > 0:
                if side > 0:
                    if c >= last_add + a:
                        target = min(max_pos, abs(pos) + add_size)
                        state["last_add"] = c
                else:
                    if c <= last_add - a:
                        target = -min(max_pos, abs(pos) + add_size)
                        state["last_add"] = c

        return {"target": target, "stop": stop, "take": take}

    # Flat: respect cooldown
    if i < int(state.get("flat_until", 0)):
        return {"target": 0.0, "stop": None, "take": None}

    # Entries are half size
    if long_signal:
        state["base"] = 0.5
        state["last_add"] = c
        state["entry_atr"] = a
        state["entry_px"] = c
        return {"target": 0.5, "stop": c - 1.5 * a, "take": c + 2.0 * a}

    if short_signal:
        state["base"] = 0.5
        state["last_add"] = c
        state["entry_atr"] = a
        state["entry_px"] = c
        return {"target": -0.5, "stop": c + 1.5 * a, "take": c - 2.0 * a}

    return {"target": 0.0, "stop": None, "take": None}

