    box_l = float(box_low[-1]) if len(box_low) else np.nan

    last_exit = int(state.get("last_exit", -10**9))
    armed = bool(state.get("armed", False))
    entry_atr = float(state.get("entry_atr", 0.0))
    anchor = float(state.get("anchor", 0.0))
    prev_pos = float(state.get("prev_pos", pos))

