            if moved > 0:
                anchor = anchor + moved * entry_atr
                state["anchor"] = anchor

            stop = anchor - 2.0 * entry_atr
            take = anchor + 3.0 * entry_atr

        if not math.isnan(box_l) and c < box_l:
