        return {"target": pos, "stop": stop, "take": take}

    state["prev_pos"] = pos

    if n - 1 - last_exit < 96:
        return {"target": pos, "stop": None, "take": None}

    if math.isnan(a) or a <= 0.0 or math.isnan(box_h) or math.isnan(box_l):
        return {"target": pos, "stop": None, "take": None}

    box_height = box_h - box_l
    if box_height <= 0.0 or box_height > 4.0 * a:
