    ema100 = ind.ema(c, 100)
    atr14 = ind.atr(hist, 14)

    i = len(hist) - 1
    close = float(c[-1])
    e20 = float(ema20[-1])
    e100 = float(ema100[-1])
    atr = float(atr14[-1])

    if not np.isfinite(e20) or not np.isfinite(e100) or not np.isfinite(atr) or atr <= 0:
        return {"target": float(pos), "stop": None, "take": None}

    cross_up = ema20[-2] <= ema100[-2] and ema20[-1] > ema100[-1]
    cross_dn = ema20[-2] >= ema100[-2] and ema20[-1] < ema100[-1]

    # Signal / target sizing
    size = 0.0025 * close / (3.0 * atr)
    if size < 0.05:
        size = 0.05
    elif size > 1.0:
        size = 1.0

    target = float(pos)
    stop = None
    take = None

    # Flat: enter on crossover
    if pos == 0.0:
        if cross_up:
            target = size
        elif cross_dn:
            target = -size
        return {"target": target, "stop": None, "take": None}

    # In a trade: opposite signal closes current position (and indicates reversal intent, but engine won't flip)
    if pos > 0 and cross_dn:
        return {"target": 0.0, "stop": None, "take": None}
    if pos < 0 and cross_up:
        return {"target": 0.0, "stop": None, "take": None}

    # Manage runner: once at least 2 ATR in profit on a close, scale to half size
    if pos > 0:
        entry = float(state.get("entry", close))
        trig = float(state.get("runner_trigger", 0.0))
        if trig == 0.0:
            trig = entry + 2.0 * atr
            state["runner_trigger"] = trig
        if close >= trig:
            target = 0.5 * pos
    else:
        entry = float(state.get("entry", close))
        trig = float(state.get("runner_trigger", 0.0))
        if trig == 0.0:
            trig = entry - 2.0 * atr
            state["runner_trigger"] = trig
        if close <= trig:
            target = 0.5 * pos

    return {"target": float(target), "stop": stop, "take": take}

