def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    high = hist.high
    low = hist.low

    n = len(hist)
    if n < 40:
        return {"target": pos, "stop": None, "take": None}

    atr = ind.atr(hist, 14)
    a = float(atr[-1])
    c = float(close[-1])

    lookback = 32
    if n <= lookback:
        return {"target": pos, "stop": None, "take": None}

    prior_high = float(np.max(high[-lookback-1:-1]))
    prior_low = float(np.min(low[-lookback-1:-1]))
    box_height = prior_high - prior_low

    long_signal = (c > prior_high) and (box_height <= 6.0 * a)

    # Persistent state
    entry_atr = float(state.get("entry_atr", 0.0))
    add_done = bool(state.get("add_done", False))
    pyramid_active = bool(state.get("pyramid_active", False))
    last_add_price = float(state.get("last_add_price", 0.0))
    entry_price = float(state.get("entry_price", 0.0))

    # Detect flat/position transitions
    if pos == 0.0:
        if "entry_atr" in state:
            del state["entry_atr"]
        if "add_done" in state:
            del state["add_done"]
        if "pyramid_active" in state:
            del state["pyramid_active"]
        if "last_add_price" in state:
            del state["last_add_price"]
        if "entry_price" in state:
            del state["entry_price"]
        target = 0.25 if long_signal else 0.0
        if target == 0.25 and target != pos:
            state["entry_atr"] = a
            state["add_done"] = False
            state["pyramid_active"] = True
            state["last_add_price"] = c
            state["entry_price"] = c
        return {"target": target, "stop": None, "take": None}

    # Long-only; if somehow not long, flatten.
    if pos < 0:
        return {"target": 0.0, "stop": None, "take": None}

    # Existing long
    if entry_atr <= 0.0:
        entry_atr = a
        state["entry_atr"] = entry_atr
    if entry_price <= 0.0:
        entry_price = c
        state["entry_price"] = entry_price
    if last_add_price <= 0.0:
        last_add_price = entry_price
        state["last_add_price"] = last_add_price

    # If a short signal prints, flat the trade. Since only long-only logic is specified,
    # use the breakdown of the box as the short signal.
    short_signal = c < prior_low
    if short_signal:
        state["pyramid_active"] = False
        return {"target": 0.0, "stop": None, "take": None}

    stop = entry_price - 2.0 * entry_atr

    # Add one extra quarter-size once, after price moves at least 2 entry ATR
    # from the last add, while still in profit.
    target = pos
    if not add_done:
        if c >= last_add_price + 2.0 * entry_atr and c > entry_price:
            target = min(0.50, pos + 0.25)
            if target > pos:
                state["add_done"] = True
                state["last_add_price"] = c

    return {"target": target, "stop": stop, "take": None}

