    h1_close = h1.close
    h1_ema20 = ind.ema(h1_close, 20)
    h1_last_close = float(h1_close[-1])
    h1_last_ema20 = float(h1_ema20[-1])

    # 48-bar Donchian breakouts using prior 48 bars
    prior_high = float(ind.highest(high[:-1], 48)[-1])
    prior_low = float(ind.lowest(low[:-1], 48)[-1])

    long_breakout = c > prior_high
    short_breakout = c < prior_low

    long_trend = h1_last_close > h1_last_ema20
    short_trend = h1_last_close < h1_last_ema20

    # Current position state
    if pos > 0:
        side = 1
        entry = state.get("entry_long", c)
        entry_atr = state.get("entry_atr_long", atrv)
        reduced = bool(state.get("reduced_long", False))
    elif pos < 0:
        side = -1
        entry = state.get("entry_short", c)
        entry_atr = state.get("entry_atr_short", atrv)
        reduced = bool(state.get("reduced_short", False))
    else:
        side = 0
        entry = c
        entry_atr = atrv
        reduced = False

    target = pos
    stop = None
    take = None

    # Signal logic
    if pos == 0:
        if long_breakout and long_trend:
            risk_frac = 0.0025
            raw = risk_frac * c / max(1e-12, atrv)
            target = min(1.0, max(0.05, raw))
            state["pending_side"] = 1
            state["pending_entry_atr"] = float(atrv)
            state["pending_entry"] = float(c)
        elif short_breakout and short_trend:
            risk_frac = 0.0025
            raw = risk_frac * c / max(1e-12, atrv)
            target = -min(1.0, max(0.05, raw))
            state["pending_side"] = -1
            state["pending_entry_atr"] = float(atrv)
            state["pending_entry"] = float(c)
        else:
            if "pending_side" in state:
                del state["pending_side"]
            if "pending_entry_atr" in state:
                del state["pending_entry_atr"]
            if "pending_entry" in state:
                del state["pending_entry"]
    elif pos > 0:
        if short_breakout and short_trend:
            target = 0.0
        else:
            # scale out once first time closing 1.5 ATR in profit
            if (not reduced) and c >= entry + 1.5 * entry_atr:
                target = 0.5 * pos
                state["reduced_long"] = True
            else:
                target = pos
            stop = entry - 2.0 * entry_atr
    else:  # pos < 0
        if long_breakout and long_trend:
            target = 0.0
        else:
            if (not reduced) and c <= entry - 1.5 * entry_atr:
                target = 0.5 * pos
                state["reduced_short"] = True
            else:
                target = pos
            stop = entry + 2.0 * entry_atr

    # Manage state transitions on flat / active position
    if pos == 0:
        if "entry_long" in state:
            del state["entry_long"]
        if "entry_atr_long" in state:
            del state["entry_atr_long"]
        if "reduced_long" in state:
            del state["reduced_long"]
        if "entry_short" in state:
            del state["entry_short"]
        if "entry_atr_short" in state:
            del state["entry_atr_short"]
        if "reduced_short" in state:
            del state["reduced_short"]

    # Persist entry metadata when opening/holding position
    if pos == 0 and target != 0:
        if target > 0:
            state["entry_long"] = float(c)
            state["entry_atr_long"] = float(atrv)
            state["reduced_long"] = False
            if "entry_short" in state:
