        and close[-1] < box_low
        and not math.isnan(ema20_4h_now)
        and close_4h_now < ema20_4h_now
    )

    # exits on opposite signal
    if pos > 0 and short_sig:
        return {"target": 0.0, "stop": None, "take": None}
    if pos < 0 and long_sig:
        return {"target": 0.0, "stop": None, "take": None}

