    if "trail_mult" not in state:
        state["trail_mult"] = 0.0
    if "pending_entry" not in state:
        state["pending_entry"] = False

    # If flat, update entry state to reflect absence of position
    if pos == 0.0:
        state["in_trade"] = False

    # Detect a fresh filled long position
    if pos > 0.0 and not state["in_trade"]:
        state["in_trade"] = True
        state["entry_price"] = cur_close
        state["entry_atr"] = cur_atr
        state["box_base"] = cur_close
        state["trail_mult"] = 0.0
