    if pos > 0.0:
        ep = float(state["entry_price"])
        ea = float(state["entry_atr"])
        if ea > 0.0 and not math.isnan(ea):
            gain = cur_close - ep
            level = int(math.floor(gain / (2.0 * ea)))
            if level > 0:
                state["box_base"] = ep + 2.0 * ea * level
                state["trail_mult"] = float(level)

            base = float(state["box_base"])
            stop = base - 2.0 * ea
            take = base + 2.0 * ea

            # Preserve hard stop/take and ratchet with profitable closes
            if stop > cur_close:
                stop = cur_close - 0.01
            if take <= cur_close:
                take = base + 2.0 * ea

    # Long-only bearish exit: if RSI crosses down through 70, flatten next open
    bearish_exit = False
    if len(hist) >= 2 and not math.isnan(rsi[-2]) and not math.isnan(cur_rsi):
