def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    high = hist.high
    low = hist.low

    n = len(hist)
    if n < 20:
        return {"target": pos, "stop": None, "take": None}

    rsi = ind.rsi(close, 14)
    atr = ind.atr(hist, 14)

    c0 = float(close[-1])
    c1 = float(close[-2])
    r0 = float(rsi[-1])
    r1 = float(rsi[-2])
    a0 = float(atr[-1])

    def snap(x):
        return round(x / 0.05) * 0.05

    def has(key):
        return key in state

    # Cooldown tracking
    if pos == 0.0:
        if not has("cooldown_until"):
            state["cooldown_until"] = -1
    else:
        if has("cooldown_until"):
            del state["cooldown_until"]

    # Detect fresh flat transition for cooldown
    prev_pos = float(state.get("prev_pos", 0.0))
    if prev_pos != 0.0 and pos == 0.0:
        state["cooldown_until"] = n - 1 + 16  # 4 hours = 16 x 15m bars

    state["prev_pos"] = pos

    cooldown_until = int(state.get("cooldown_until", -1))
    in_cooldown = pos == 0.0 and n - 1 < cooldown_until

    # Manage existing trade state
    if pos != 0.0:
        side = 1 if pos > 0 else -1
        entry_atr = float(state.get("entry_atr", a0 if math.isfinite(a0) else 0.0))
        anchor = float(state.get("anchor", c0))
        last_add = float(state.get("last_add", c0))
        adds = int(state.get("adds", 0))

        # Ratchet anchor every time close clears another 2 ATR past current anchor
        if math.isfinite(entry_atr) and entry_atr > 0:
            while side * (c0 - anchor) >= 2.0 * entry_atr:
                anchor += side * 2.0 * entry_atr

        # Stops / takes based on current anchor
        stop = anchor - side * 2.0 * entry_atr
        take = anchor + side * 3.0 * entry_atr

        # Add once at +1 ATR beyond last add, capped at full size
        target = pos
        if adds < 1 and math.isfinite(entry_atr) and entry_atr > 0:
            if side > 0 and c0 >= last_add + 1.0 * entry_atr and pos < 1.0:
                target = snap(min(1.0, pos + 0.25))
                if target > pos:
                    state["last_add"] = c0
                    state["adds"] = 1
            elif side < 0 and c0 <= last_add - 1.0 * entry_atr and pos > -1.0:
                target = snap(max(-1.0, pos - 0.25))
                if target < pos:
                    state["last_add"] = c0
                    state["adds"] = 1

        state["entry_atr"] = entry_atr
        state["anchor"] = anchor
        return {"target": target, "stop": stop, "take": take}

    # Flat
    if in_cooldown:
        return {"target": pos, "stop": None, "take": None}

    long_signal = r1 <= 20.0 and r0 > 20.0
    short_signal = r1 >= 80.0 and r0 < 80.0

    if long_signal and not short_signal:
        target = 0.25
        if math.isfinite(a0):
            state["entry_atr"] = a0
        else:
            state["entry_atr"] = 0.0
        state["anchor"] = c0
        state["last_add"] = c0
        state["adds"] = 0
        return {"target": target, "stop": c0 - 2.0 * state["entry_atr"], "take": c0 + 3.0 * state["entry_atr"]}

    if short_signal and not long_signal:
        target = -0.25
        if math.isfinite(a0):
            state["entry_atr"] = a0
        else:
            state["entry_atr"] = 0.0
        state["anchor"] = c0
        state["last_add"] = c0
        state["adds"] = 0
        return {"target": target, "stop": c0 + 2.0 * state["entry_atr"], "take": c0 - 3.0 * state["entry_atr"]}

    return {"target": pos, "stop": None, "take": None}

