    cooldown = int(state.get("cooldown", 0))
    prev_pos = float(state.get("prev_pos", 0.0))
    if prev_pos != 0.0 and pos == 0.0:
        cooldown = 4
    if cooldown > 0 and pos == 0.0:
        cooldown -= 1
    state["cooldown"] = int(cooldown)
    state["prev_pos"] = float(pos)

    target = float(pos)
    stop = None
    take = None

    # Need enough history for 32-bar box and 4h EMA20
    if len(hist) < 960:
        return {"target": target, "stop": stop, "take": take}

    close = float(hist.close[-1])

    # 32-bar box excluding current bar
    prior_high = float(np.max(hist.high[-33:-1]))
    prior_low = float(np.min(hist.low[-33:-1]))
    box_height = prior_high - prior_low

    atr14 = float(ind.atr(hist, 14)[-1])
    if not np.isfinite(atr14) or atr14 <= 0:
        return {"target": target, "stop": stop, "take": take}

    if box_height > 3.0 * atr14:
        return {"target": target, "stop": stop, "take": stop}

