    h4_ema20 = float(ind.ema(h4.close, 20)[-1])
    if not np.isfinite(h4_ema20):
        return {"target": target, "stop": stop, "take": take}

    long_ok = h4_close > h4_ema20
    short_ok = h4_close < h4_ema20

    # If in a trade and an opposite signal appears, flatten.
    if pos > 0 and close < prior_low:
        target = 0.0
    elif pos < 0 and close > prior_high:
        target = 0.0
    else:
        # Only open when flat, after cooldown
        if pos == 0.0 and cooldown == 0:
            if close > prior_high and long_ok:
                target = 0.5
            elif close < prior_low and short_ok:
                target = -0.5
        else:
            target = float(pos)

    return {"target": float(target), "stop": stop, "take": take}

