import math
import numpy as np


def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    rsi = ind.rsi(close, 21)
    atr = ind.atr(hist, 14)

    t = len(hist) - 1
    cur_close = float(close[-1])
    cur_rsi = float(rsi[-1]) if not np.isnan(rsi[-1]) else np.nan
    prev_rsi = float(rsi[-2]) if len(hist) > 1 and not np.isnan(rsi[-2]) else np.nan
    cur_atr = float(atr[-1]) if not np.isnan(atr[-1]) else np.nan

    day = int(hist.time[-1] // 86400000)

    if "day" not in state or int(state["day"]) != day:
        state["day"] = day
        state["entries"] = 0

    h4 = hist.htf(240)
    h4_close = h4.close
    h4_ema20 = ind.ema(h4_close, 20)
    trend_long = False
    trend_short = False
    if len(h4_close) > 0 and not np.isnan(h4_ema20[-1]):
        trend_long = float(h4_close[-1]) > float(h4_ema20[-1])
        trend_short = float(h4_close[-1]) < float(h4_ema20[-1])

    cross_up = False
    cross_down = False
    if len(hist) > 1 and not np.isnan(cur_rsi) and not np.isnan(prev_rsi):
        cross_up = prev_rsi <= 25.0 and cur_rsi > 25.0
        cross_down = prev_rsi >= 75.0 and cur_rsi < 75.0

    target = float(pos)
    stop = None
    take = None

    if pos == 0.0:
        if int(state.get("entries", 0)) < 3:
            if cross_up and trend_long:
                target = 0.5
                state["entries"] = int(state.get("entries", 0)) + 1
                if not np.isnan(cur_atr):
                    state["dir"] = 1
                    state["entry_extreme"] = cur_close
                    state["entry_atr"] = cur_atr
            elif cross_down and trend_short:
                target = -0.5
                state["entries"] = int(state.get("entries", 0)) + 1
                if not np.isnan(cur_atr):
                    state["dir"] = -1
                    state["entry_extreme"] = cur_close
                    state["entry_atr"] = cur_atr

    elif pos > 0.0:
        if cross_down:
            target = 0.0
            for k in ("dir", "entry_extreme", "entry_atr"):
                if k in state:
                    del state[k]
        else:
            if int(state.get("dir", 1)) == 1:
                ext = float(state.get("entry_extreme", cur_close))
                if cur_close > ext:
                    ext = cur_close
                    state["entry_extreme"] = ext
                use_atr = float(state.get("entry_atr", cur_atr))
                if not np.isnan(use_atr):
                    stop = ext - 3.0 * use_atr

    elif pos < 0.0:
        if cross_up:
            target = 0.0
            for k in ("dir", "entry_extreme", "entry_atr"):
                if k in state:
                    del state[k]
        else:
            if int(state.get("dir", -1)) == -1:
                ext = float(state.get("entry_extreme", cur_close))
                if cur_close < ext:
                    ext = cur_close
                    state["entry_extreme"] = ext
                use_atr = float(state.get("entry_atr", cur_atr))
                if not np.isnan(use_atr):
                    stop = ext + 3.0 * use_atr

    if pos == 0.0 and target == 0.0:
        if "dir" in state:
            del state["dir"]
        if "entry_extreme" in state:
            del state["entry_extreme"]
        if "entry_atr" in state:
            del state["entry_atr"]

    return {"target": float(target), "stop": stop, "take": take}
